#!/usr/bin/env node
/**
 * GENERATED FIXTURE, NOT A RECORDED STREAM. Writes `long-trace.ndjson` next to this file: one session whose trace has exactly
 * 1000 rows (plan M7 T12, smoke S8: the windowed trace above 200 rows). Spec §16.1 asks fixtures to be recordings of the real
 * CLI; this one is outside that rule on purpose (a 1000-row real session would cost a long paid run and prove nothing more).
 * It is only for the smoke stack's Fake driver and is shaped like the recorded ones: the `init` and `result` lines are copied
 * from `basic.ndjson`, and every assistant message streams as message_start → content_block_start → assistant → content_block_stop
 * → message_delta → message_stop, followed by the user `tool_result` lines.
 *
 * Rows: assistant messages of one reasoning row and 3–5 read-only tool calls (Read, Grep, Glob, Bash: no file writes, so the
 * runner never hashes files for them), a short prose row every tenth message, and a final reasoning + answer.
 *
 *   node tests/fixtures/claude-streams/make-long-trace.mjs
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';

const ROWS = 1000;
const dir = import.meta.dirname;
const basic = readFileSync(resolve(dir, 'basic.ndjson'), 'utf8').trim().split('\n').map((l) => JSON.parse(l));
const SESSION = '00000000-0000-4000-8000-000000100000';
const CWD = '/home/user/gpu-server/VideoGen/spikes/m7/work/long-trace';
const MODEL = 'claude-haiku-4-5-20251001';

let uuidN = 100001;
const uuid = () => `00000000-0000-4000-8000-${String(uuidN++).padStart(12, '0')}`;
let t = 600;
const out = [];
const line = (m, gap = 12) => { t += gap; out.push({ t, m }); };
const stream = (event) => line({ type: 'stream_event', event, session_id: SESSION, parent_tool_use_id: null, uuid: uuid() }, 2);
const usage = (output) => ({
  input_tokens: 8, cache_creation_input_tokens: 0, cache_read_input_tokens: 31_200,
  cache_creation: { ephemeral_5m_input_tokens: 0, ephemeral_1h_input_tokens: 0 }, output_tokens: output, service_tier: 'standard', inference_geo: 'not_available',
});
const message = (id, content, output) => ({
  model: MODEL, id, type: 'message', role: 'assistant', content, container: null, stop_reason: null, stop_sequence: null, stop_details: null,
  usage: usage(output), input_transformations: [], diagnostics: null, context_management: null,
});

const init = structuredClone(basic.find((l) => l.m.type === 'system' && l.m.subtype === 'init'));
Object.assign(init.m, { cwd: CWD, session_id: SESSION, uuid: uuid() });
out.push({ t, note: 'generated by make-long-trace.mjs: not a recorded stream (outside spec §16.1), smoke S8 only', m: init.m });

const FILES = ['scene/product.py', 'scene/parts/cap.py', 'scene/parts/barrel.py', 'scene/parts/spring.py', 'scene/parts/refill.py', 'scene/lights.py', 'scene/camera.py', 'render/config.json'];
const tool = (k, j) => {
  const f = FILES[(k + j) % FILES.length];
  switch ((k + j) % 4) {
    case 0: return { name: 'Read', input: { file_path: `${CWD}/${f}` }, result: `     1\t# ${f}\n     2\timport bpy\n` };
    case 1: return { name: 'Grep', input: { pattern: `def part_${k % 9}`, path: CWD }, result: `${f}:${12 + j}:def part_${k % 9}():` };
    case 2: return { name: 'Glob', input: { pattern: `scene/**/*${j}.py` }, result: f };
    default: return { name: 'Bash', input: { command: `python3 -m py_compile ${f}`, description: 'Check the file compiles' }, result: '' };
  }
};

let rows = 0;
let k = 0;
const budget = ROWS - 2; // the final message adds reasoning + answer
while (rows < budget) {
  const id = `msg_01LongTrace${String(k).padStart(4, '0')}`;
  const blocks = [{ type: 'thinking', thinking: `Step ${k + 1}: checking ${FILES[k % FILES.length]} before the next change; the parts must stay aligned with the storyboard.`, signature: 'redacted' }];
  if (k % 10 === 9 && budget - rows >= 2) blocks.push({ type: 'text', text: `Ara not: ${k + 1} adım bitti, sahne derleniyor.` });
  const n = Math.min(3 + (k % 3), budget - rows - blocks.length);
  const calls = [];
  for (let j = 0; j < n; j++) calls.push({ id: `toolu_01LongTrace${String(k).padStart(4, '0')}x${j}`, ...tool(k, j) });
  stream({ type: 'message_start', message: message(id, [], 3) });
  [...blocks, ...calls.map((c) => ({ type: 'tool_use', id: c.id, name: c.name, input: c.input, caller: { type: 'direct' } }))].forEach((b, index) => {
    const start = b.type === 'tool_use' ? { type: 'tool_use', id: b.id, name: b.name, input: {}, caller: { type: 'direct' } } : b.type === 'thinking' ? { type: 'thinking', thinking: '', signature: 'redacted' } : { type: 'text', text: '' };
    stream({ type: 'content_block_start', index, content_block: start });
    line({ type: 'assistant', message: message(id, [b], 3), parent_tool_use_id: null, session_id: SESSION, uuid: uuid() }, 20);
    stream({ type: 'content_block_stop', index });
  });
  stream({ type: 'message_delta', delta: { stop_reason: 'tool_use', stop_sequence: null, stop_details: null, container: null }, usage: { ...usage(60 + 20 * n), output_tokens_details: { thinking_tokens: 30 } }, context_management: { applied_edits: [] } });
  stream({ type: 'message_stop' });
  for (const c of calls) {
    line({ type: 'user', message: { role: 'user', content: [{ tool_use_id: c.id, type: 'tool_result', content: c.result }] }, parent_tool_use_id: null, session_id: SESSION, uuid: uuid(), timestamp: new Date(Date.UTC(2026, 9, 8, 9, 0, 0) + t).toISOString() }, 8);
  }
  rows += blocks.length + calls.length;
  k += 1;
}

const last = `msg_01LongTrace${String(k).padStart(4, '0')}`;
stream({ type: 'message_start', message: message(last, [], 1) });
const answer = `Bitti: ${k} adımda sahne dosyaları okundu ve derlendi.`;
[{ type: 'thinking', thinking: 'All parts compile; the scene is ready for the build step.', signature: 'redacted' }, { type: 'text', text: answer }].forEach((b, index) => {
  stream({ type: 'content_block_start', index, content_block: b.type === 'thinking' ? { type: 'thinking', thinking: '', signature: 'redacted' } : { type: 'text', text: '' } });
  line({ type: 'assistant', message: message(last, [b], 1), parent_tool_use_id: null, session_id: SESSION, uuid: uuid() }, 20);
  stream({ type: 'content_block_stop', index });
});
rows += 2;
stream({ type: 'message_delta', delta: { stop_reason: 'end_turn', stop_sequence: null, stop_details: null, container: null }, usage: { ...usage(40), output_tokens_details: { thinking_tokens: 20 } }, context_management: { applied_edits: [] } });
stream({ type: 'message_stop' });

const result = structuredClone(basic.find((l) => l.m.type === 'result'));
Object.assign(result.m, { session_id: SESSION, uuid: uuid(), num_turns: k + 1, result: answer, duration_ms: t, duration_api_ms: t });
line(result.m, 10);

if (rows !== ROWS) throw new Error(`expected ${ROWS} rows, built ${rows}`);
writeFileSync(resolve(dir, 'long-trace.ndjson'), `${out.map((l) => JSON.stringify(l)).join('\n')}\n`);
process.stdout.write(`long-trace.ndjson: ${out.length} lines, ${rows} trace rows, ${k + 1} assistant messages\n`);
